package onnx

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"slices"
	"testing"
)

// The three inputs were generated by Go's AVX512 acoustic profile and explicitly
// supplied to a local AVX2 original. This tests the vocoder with different data;
// it does not assert that the originating sentence matches an ordinary original.
func TestOriginalVocoderSyntheticAVX512Inputs(t *testing.T) {
	raw, err := os.ReadFile("testdata/vocoder_synthetic_avx512_inputs.json")
	if err != nil {
		t.Fatal(err)
	}
	var ref struct {
		Synthetic bool
		ModelHash string `json:"model_sha256"`
		Count     int    `json:"value_count"`
		Hash      string `json:"output_sha256"`
		WaveCount int    `json:"wave_count"`
		WaveHash  string `json:"native_wave_sha256"`
		Inputs    map[string]struct {
			Shape []int64
			Data  []byte
		}
		Operators []struct {
			Node, Op string
			Names    []string
		}
	}
	if err = json.Unmarshal(raw, &ref); err != nil {
		t.Fatal(err)
	}
	model := "../../assets/synth/vocoder.onnx"
	data, err := os.ReadFile(model)
	if err != nil {
		t.Fatal(err)
	}
	if !ref.Synthetic || fmt.Sprintf("%x", sha256.Sum256(data)) != ref.ModelHash || len(ref.Inputs) != 3 || len(ref.Operators) != 126 || ref.Count != 46918503 || ref.WaveCount != 26400 {
		t.Fatal("synthetic reference provenance/count differs")
	}
	g, err := OpenGraph(model)
	if err != nil {
		t.Fatal(err)
	}
	inputs := map[string]Value{}
	for _, name := range []string{"f0", "bap", "spc"} {
		x, ok := ref.Inputs[name]
		if !ok {
			t.Fatal("missing input", name)
		}
		count := int64(1)
		for _, d := range x.Shape {
			if d < 1 || d > 1000000/count {
				t.Fatal("invalid input extent")
			}
			count *= d
		}
		if len(x.Data) != int(count)*4 {
			t.Fatal("input storage extent differs")
		}
		v := Value{Kind: 1, Shape: x.Shape, F: make([]float32, count)}
		for i := range v.F {
			v.F[i] = math.Float32frombits(binary.LittleEndian.Uint32(x.Data[i*4:]))
		}
		inputs[name] = v
	}
	names := []string{"wave"}
	seen := map[string]bool{"wave": true}
	outputs := map[string]bool{}
	for _, r := range ref.Operators {
		if len(r.Names) != 4 || outputs[r.Names[3]] {
			t.Fatal("invalid synthetic operator mapping")
		}
		outputs[r.Names[3]] = true
		i, ok := g.producer[r.Names[3]]
		if !ok {
			t.Fatal("missing synthetic operator")
		}
		n := g.nodes[i]
		if n.name != r.Node || n.op != r.Op || (n.op != "Conv" && n.op != "ConvTranspose") || !slices.Equal(n.inputs, r.Names[:3]) {
			t.Fatal("synthetic operator mapping differs")
		}
		for _, name := range r.Names {
			if !seen[name] {
				seen[name] = true
				names = append(names, name)
			}
		}
	}
	got, err := g.RunOriginalKernelsWithThreads(inputs, names, 1)
	if err != nil {
		t.Fatal(err)
	}
	h := sha256.New()
	total := 0
	add := func(v Value) {
		if v.Kind != 1 {
			t.Fatal("non-FLOAT output")
		}
		b := make([]byte, len(v.F)*4)
		for i, f := range v.F {
			binary.LittleEndian.PutUint32(b[i*4:], math.Float32bits(f))
		}
		h.Write(b)
		total += len(v.F)
	}
	for _, r := range ref.Operators {
		for _, j := range []int{0, 3, 1, 2} {
			add(got[r.Names[j]])
		}
	}
	if total != ref.Count || fmt.Sprintf("%x", h.Sum(nil)) != ref.Hash {
		t.Fatalf("126 synthetic-input original operators differ: values=%d hash=%x", total, h.Sum(nil))
	}
	h.Reset()
	total = 0
	add(got["wave"])
	if total != ref.WaveCount || fmt.Sprintf("%x", h.Sum(nil)) != ref.WaveHash {
		t.Fatalf("synthetic-input original wave differs: values=%d hash=%x", total, h.Sum(nil))
	}
}
